from typing import Iterable, Sequence


def _to_vector(value: Iterable[float]) -> list[float]:
    return [float(x) for x in value]


def cosine_similarity(embedding_a: Sequence[float], embedding_b: Sequence[float]) -> float:
    a = _to_vector(embedding_a)
    b = _to_vector(embedding_b)
    if len(a) != len(b):
        raise ValueError("Embedding vectors must have the same length.")
    if not a:
        raise ValueError("Embedding vectors must not be empty.")

    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    if norm_a == 0.0 or norm_b == 0.0:
        raise ValueError("Embedding vectors must not be zero vectors.")
    return dot / (norm_a * norm_b)


